effect.shader:
float random(vec2 st) {
return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}
vec2 random2(vec2 st) {
return vec2( random(st), random(st + vec2(1.0, 1.0)) );
}
void main(){
vec2 fragCoord = acScreenNorm * acScreenSize;
vec2 uv = acScreenNorm;
vec4 originalColor = texture2DCv(inputImg.texture, uv);
float t = floor((acTime * timeSpeed + seed*0.001) * glitchRate);
float glitchTrigger = random(vec2(t, 0.0));
if (glitchTrigger > flickerThreshold) {
float tearY = random(vec2(t, 2.0));
float tearHeight = tearHeightMin + random(vec2(t, 3.0)) * tearHeightRand;
float tearOffset = (random(vec2(t, 4.0)) - 0.5) * (tearOffsetMax*2.0);
if (uv.y > tearY && uv.y < tearY + max(tearHeight, 0.0)) {
float isColorBand = random(vec2(t, 5.0));
if (enableColorBands && isColorBand > bandProbThr) {
vec2 duv = uv; duv.x = fract(duv.x + tearOffset);
vec4 displacedColor = texture2DCv(inputImg.texture, duv);
vec3 bandColor = vec3(
random(vec2(t, 6.0)),
random(vec2(t, 7.0)),
random(vec2(t, 8.0))
);
displacedColor.rgb = mix(displacedColor.rgb, bandColor, clamp(bandMix,0.0,1.0));
float scanLine = sin(fragCoord.y * tearScanFreq) * tearScanAmp;
displacedColor.rgb = clamp(displacedColor.rgb - scanLine, 0.0, 1.0);
originalColor = displacedColor;
} else {
vec2 duv = uv; duv.x = fract(duv.x + tearOffset);
originalColor = texture2DCv(inputImg.texture, duv);
}
}
float gridX = blockGridMin + random(vec2(t, 9.0)) * blockGridRand;
vec2 blockGrid = floor(uv * vec2(max(1.0, gridX), max(1.0, blockGridY)));
float blockTrigger = random(blockGrid + t);
if (blockTrigger > blockAffectThr) {
float blockType = random(blockGrid + 10.0 + t);
if (blockType > staticProbThr) {
vec2 sc = fract(uv * 10.0);
originalColor.rgb = clamp(vec3(
random(sc),
random(sc.yx),
random(uv)
), 0.0, 1.0);
} else {
vec2 ro = (random2(blockGrid + 23.0) - 0.5) * 2.0;
originalColor = texture2DCv(inputImg.texture, fract(uv + ro));
}
}
}
gl_FragColor = originalColor;
}
